import {idOf,isShiny,ITEMS} from './model.mjs';
export class PartyNetwork {
 constructor(g){this.g=g;this.peer=null;this.host=null;this.players=[];this.connections=new Map();this.myId='solo';this.status='';this.guest=false}
 reset(){this.peer?.destroy();this.peer=null;this.host=null;this.players=[];this.connections.clear();this.myId='solo';this.guest=false}
 create(){if(!window.Peer)return this.g.toast('Le service de salons est indisponible. Le jeu solo reste accessible.');this.reset();this.status='Création du salon…';this.g.route('friends');this.peer=new window.Peer();this.peer.on('open',id=>{this.myId=id;this.status='Salon prêt. Partage le code à tes amis.';this.g.route('friends')});this.peer.on('error',e=>{this.status='Connexion impossible : '+e.type;this.g.toast(this.status)});this.peer.on('connection',c=>{c.on('open',()=>{if(this.connections.size>=3||this.g.battle.active){c.send({type:'error',message:'Salon complet ou combat déjà commencé.'});setTimeout(()=>c.close(),200);return}this.connections.set(c.peer,c)});c.on('data',d=>this.handleGuest(c,d));c.on('close',()=>{this.connections.delete(c.peer);this.players=this.players.filter(p=>p.pid!==c.peer);this.g.toast('Un allié a quitté le salon.');this.g.battle.removePlayer(c.peer);if(this.g.page==='friends')this.g.render()})})}
 handleGuest(c,d){if(!this.connections.has(c.peer)||!d||typeof d!=='object')return;if(d.type==='ready'&&!this.g.battle.active){const keys=[...new Set(Array.isArray(d.keys)?d.keys:[])].filter(k=>/^\d{1,4}s?$/.test(String(k))&&this.g.dex[idOf(k)]).map(String).slice(0,6);if(!keys.length)return;const items={};for(const k of keys)if(ITEMS.some(i=>i.key===d.items?.[k]))items[k]=d.items[k];this.players=this.players.filter(p=>p.pid!==c.peer);this.players.push({pid:c.peer,name:'Allié '+(this.players.length+1),keys,items});c.send({type:'ready-accepted'});if(this.g.page==='friends')this.g.render()}if(d.type==='action')this.g.battle.remoteAction(c.peer,d.action,d.battleId)}
 join(code){code=code.trim();if(!code)return this.g.toast('Entre le code du salon.');if(!window.Peer)return this.g.toast('Le service de salons est indisponible.');this.reset();this.guest=true;this.status='Connexion au salon…';this.peer=new window.Peer();this.peer.on('open',id=>{this.myId=id;this.host=this.peer.connect(code,{reliable:true});this.host.on('open',()=>this.sendReady());this.host.on('data',d=>{if(d.type==='error')this.g.toast(d.message);if(d.type==='ready-accepted'){this.status='Équipe reçue. En attente de l’hôte.';if(this.g.page==='friends')this.g.render()}if(d.type==='battle-end-room'){if(this.g.battle.active)this.g.battle.stop();return}if(typeof d.type==='string'&&d.type.startsWith('battle-'))this.g.battle.receive(d)});this.host.on('close',()=>{this.guest=false;this.host=null;this.status='Le salon a été fermé.';if(this.g.battle.active)this.g.battle.stop();this.g.toast(this.status)})});this.peer.on('error',e=>{this.status='Connexion : '+e.type;this.g.toast(this.status)});this.g.render()}
 sendReady(){if(!this.host?.open)return;const s=this.g.state;this.host.send({type:'ready',keys:s.team,items:Object.fromEntries(s.team.map(k=>[k,this.g.held(k).key]))});this.g.toast('Ton équipe a été envoyée à l’hôte.')}
 broadcast(message){for(const c of this.connections.values())if(c.open)c.send(message)}
}
